<script setup lang="ts">
import { lazyStrings } from '@/strings';
import { ChevronRightIcon, LockIcon } from 'lucide-vue-next';
import FileExplorerEntryIcon from './FileExplorerEntryIcon.vue';
import FileExplorerListEntryRow from './FileExplorerListEntryRow.vue';
import FileExplorerRenameInput from './FileExplorerRenameInput.vue';
import type { FileExplorerEntry } from '@/features/file-explorer/logic/types';
import { formatSize, formatDate } from '@/features/file-explorer/logic/utils';
import { useFileExplorerLongPress } from '@/features/file-explorer/composables/useFileExplorerLongPress';

const props = defineProps<{
  entry: FileExplorerEntry,
  isSelected: boolean,
  isFocused: boolean,
  isRenaming: boolean,
  isCut: boolean,
  isDragTarget: boolean,
  displayMode: 'icon' | 'list' | 'column',
}>();

const emit = defineEmits<{
  (e: 'click', payload: { event: MouseEvent }): void,
  (e: 'dblclick'): void,
  (e: 'contextmenu', payload: { event: MouseEvent }): void,
  (e: 'rename-confirm', payload: { newName: string }): void,
  (e: 'rename-cancel'): void,
  (e: 'dragstart', payload: { event: DragEvent }): void,
  (e: 'dragover', payload: { event: DragEvent }): void,
  (e: 'dragleave'): void,
  (e: 'drop', payload: { event: DragEvent }): void,
}>();

const longPress = useFileExplorerLongPress({
  onLongPress: ({ event }) => emit('contextmenu', { event }),
  isEnabled: () => !props.isRenaming,
});

function onClick({ event }: { event: MouseEvent }): void {
  if (longPress.consumeClick({ event })) return;
  emit('click', { event });
}

function onContextMenu({ event }: { event: MouseEvent }): void {
  longPress.cancel();
  emit('contextmenu', { event });
}

defineExpose({
  ...((__BUILD_MODE_IS_TEST__ && {
    TEST_ONLY: {
      // Export internal state and logic used only for testing here. Do not reference these in production logic.
    },
  }) || {}),
});
</script>

<template>
  <!-- LIST MODE ROW -->
  <FileExplorerListEntryRow
    v-if="displayMode === 'list'"
    :data-testid="`entry-item-${entry.name}`"
    :entry="entry"
    :appearance="isSelected ? 'selected' : isFocused ? 'focused' : 'default'"
    :tw-class="[
      'cursor-pointer',
      isDragTarget ? 'ring-2 ring-blue-400 ring-inset' : '',
      isCut ? 'opacity-50' : '',
    ]"
    :draggable="!isRenaming"
    @pointerdown="longPress.onPointerDown({ event: $event })"
    @click="onClick({ event: $event })"
    @dblclick="emit('dblclick')"
    @contextmenu="onContextMenu({ event: $event })"
    @dragstart="emit('dragstart', { event: $event })"
    @dragover.prevent="emit('dragover', { event: $event })"
    @dragleave="emit('dragleave')"
    @drop.prevent="emit('drop', { event: $event })"
  >
    <template #name>
      <FileExplorerRenameInput
        v-if="isRenaming"
        :current-name="entry.name"
        @confirm="emit('rename-confirm', { newName: $event })"
        @cancel="emit('rename-cancel')"
      />
      <span
        v-else
        :tw-class="['text-xs truncate block', isSelected ? 'text-white' : 'text-gray-800 dark:text-gray-200']"
      >
        {{ entry.name }}
      </span>
    </template>

    <template #trailing>
      <span :tw-class="['text-[10px] font-mono w-16 text-right shrink-0', isSelected ? 'text-blue-100' : 'text-gray-400 dark:text-gray-500']">
        {{ entry.kind === 'file' ? formatSize({ bytes: entry.size }) : '' }}
      </span>
      <span :tw-class="['text-[10px] w-28 text-right shrink-0 hidden md:block', isSelected ? 'text-blue-100' : 'text-gray-400 dark:text-gray-500']">
        {{ entry.kind === 'file' ? formatDate({ timestamp: entry.lastModified }) : '' }}
      </span>
      <span :tw-class="['text-[10px] w-16 text-right shrink-0 hidden lg:block uppercase', isSelected ? 'text-blue-100' : 'text-gray-400 dark:text-gray-500']">
        {{ entry.kind === 'file' ? (entry.extension || '—') : lazyStrings.fileExplorer__folder() }}
      </span>
    </template>
  </FileExplorerListEntryRow>

  <!-- ICON MODE CARD -->
  <div
    v-else-if="displayMode === 'icon'"
    :data-testid="`entry-item-${entry.name}`"
    :tw-class="['group flex flex-col items-center gap-1.5 p-2 rounded-xl cursor-pointer select-none transition-all w-24',
                isSelected
                  ? 'bg-blue-500 text-white'
                  : isFocused
                    ? 'bg-gray-100 dark:bg-gray-800'
                    : 'hover:bg-gray-100 dark:hover:bg-gray-800',
                isDragTarget ? 'ring-2 ring-blue-400 ring-inset' : '',
                isCut ? 'opacity-50' : '',
    ]"
    :draggable="!isRenaming"
    @pointerdown="longPress.onPointerDown({ event: $event })"
    @click="onClick({ event: $event })"
    @dblclick="emit('dblclick')"
    @contextmenu="onContextMenu({ event: $event })"
    @dragstart="emit('dragstart', { event: $event })"
    @dragover.prevent="emit('dragover', { event: $event })"
    @dragleave="emit('dragleave')"
    @drop.prevent="emit('drop', { event: $event })"
  >
    <FileExplorerEntryIcon
      :kind="entry.kind"
      :extension="entry.extension"
      :mime-category="entry.mimeCategory"
      size="lg"
    />
    <FileExplorerRenameInput
      v-if="isRenaming"
      :current-name="entry.name"
      @confirm="emit('rename-confirm', { newName: $event })"
      @cancel="emit('rename-cancel')"
    />
    <span
      v-else
      :tw-class="['text-[11px] text-center leading-tight break-all line-clamp-2 w-full px-1', isSelected ? 'text-white' : 'text-gray-700 dark:text-gray-300']"
    >{{ entry.name }}</span>
    <LockIcon
      v-if="entry.readOnly"
      :tw-class="['w-2.5 h-2.5 shrink-0 opacity-50 absolute top-1 right-1', isSelected ? 'text-white' : 'text-gray-400 dark:text-gray-500']"
      data-testid="entry-lock-icon"
    />
  </div>

  <!-- COLUMN MODE ROW -->
  <div
    v-else-if="displayMode === 'column'"
    :data-testid="`entry-item-${entry.name}`"
    :tw-class="['flex items-center gap-2 px-2 py-1.5 cursor-pointer select-none rounded-md transition-all',
                isSelected
                  ? 'bg-blue-500 text-white'
                  : isFocused
                    ? 'bg-gray-100 dark:bg-gray-800'
                    : 'hover:bg-gray-100 dark:hover:bg-gray-800',
                isCut ? 'opacity-50' : '',
    ]"
    @pointerdown="longPress.onPointerDown({ event: $event })"
    @click="onClick({ event: $event })"
    @dblclick="emit('dblclick')"
    @contextmenu="onContextMenu({ event: $event })"
  >
    <FileExplorerEntryIcon
      :kind="entry.kind"
      :extension="entry.extension"
      :mime-category="entry.mimeCategory"
      size="sm"
    />
    <FileExplorerRenameInput
      v-if="isRenaming"
      :current-name="entry.name"
      @confirm="emit('rename-confirm', { newName: $event })"
      @cancel="emit('rename-cancel')"
    />
    <span v-else :tw-class="['text-xs flex-1 truncate', isSelected ? 'text-white' : 'text-gray-700 dark:text-gray-300']">
      {{ entry.name }}
    </span>
    <LockIcon
      v-if="entry.readOnly"
      :tw-class="['w-2.5 h-2.5 shrink-0 opacity-50', isSelected ? 'text-white' : 'text-gray-400 dark:text-gray-500']"
      data-testid="entry-lock-icon"
    />
    <ChevronRightIcon
      v-if="entry.kind === 'directory'"
      :tw-class="['w-3 h-3 shrink-0', isSelected ? 'text-blue-100' : 'text-gray-400']"
    />
  </div>
</template>
