<script setup lang="ts">
import { lazyStrings } from '@/strings';
import { computed } from 'vue';
import { XIcon } from 'lucide-vue-next';
import { useFileExplorerModal, mapFileExplorerModalOptionsToRootDescriptor } from '@/features/file-explorer/composables/useFileExplorerModal';
import FileExplorer from './FileExplorer.vue';

const { closeFileExplorer, fileExplorerOptions } = useFileExplorerModal();

const initialLocked = computed(() => fileExplorerOptions.value.kind === 'opfs-root');

const title = computed(() => {
  const options = fileExplorerOptions.value;
  switch (options.kind) {
  case 'opfs-root':
    return lazyStrings.fileExplorer__file_explorer_opfs();
  case 'native-directory':
  case 'wesh-mounts':
    return options.title;
  default: {
    const _exhaustiveCheck: never = options;
    throw new Error(`Unhandled file explorer modal options: ${JSON.stringify(_exhaustiveCheck)}`);
  }
  }
});

const initialPath = computed(() => {
  const options = fileExplorerOptions.value;
  switch (options.kind) {
  case 'opfs-root':
    return undefined;
  case 'native-directory':
  case 'wesh-mounts':
    return options.initialPath;
  default: {
    const _exhaustiveCheck: never = options;
    throw new Error(`Unhandled file explorer modal options: ${JSON.stringify(_exhaustiveCheck)}`);
  }
  }
});

const root = computed(() => mapFileExplorerModalOptionsToRootDescriptor({
  options: fileExplorerOptions.value,
}));


defineExpose({
  ...((__BUILD_MODE_IS_TEST__ && {
    TEST_ONLY: {
      // Export internal state and logic used only for testing here. Do not reference these in production logic.
    },
  }) || {}),
});

import "virtual:naidan-tailwind-css-module/b521e235b4efb22b5e330a04e4d91f8c39b2c049a3cdff309119a66c11397e7d.js";
import "virtual:naidan-tailwind-css-module/ebecc4fd674ef82f183437255486fe38e6831e60d5730478c48be6aabd6a8f8f.js";
</script>

<template>
  <Teleport to="body">
    <div
      tw-class="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm"
      data-testid="file-explorer-modal"
      @click.self="closeFileExplorer()"
    >
      <div tw-class="flex flex-col w-full max-w-5xl h-[95vh] md:h-[90vh] bg-white dark:bg-gray-900 rounded-2xl shadow-2xl overflow-hidden border border-gray-200 dark:border-gray-700">
        <div tw-class="flex items-center justify-between px-4 py-2.5 border-b border-gray-200 dark:border-gray-700 shrink-0">
          <span tw-class="text-sm font-semibold text-gray-700 dark:text-gray-200">{{ title }}</span>
          <button
            tw-class="p-1.5 rounded-lg text-gray-400 hover:text-gray-600 dark:hover:text-gray-200 hover:bg-gray-100 dark:hover:bg-gray-800 transition-colors"
            :title="lazyStrings.fileExplorer__close()"
            data-testid="file-explorer-modal-close"
            @click="closeFileExplorer()"
          >
            <XIcon tw-class="w-4 h-4" />
          </button>
        </div>

        <div tw-class="flex-1 overflow-hidden">
          <Suspense>
            <FileExplorer
              :root="root"
              :initial-path="initialPath"
              :initial-locked="initialLocked"
              initial-view-mode="list"
              initial-preview-visibility="visible"
              tw-class="h-full"
            />
          </Suspense>
        </div>
      </div>
    </div>
  </Teleport>
</template>
